mod tests;

use std::hash::keccak::keccakf1600;
use std::runtime::is_unconstrained;

global BLOCK_SIZE_IN_BYTES: u32 = 136; //(1600 - BITS * 2) / WORD_SIZE;
global WORD_SIZE: u32 = 8; // Limbs are made up of u64s so 8 bytes each.
global LIMBS_PER_BLOCK: u32 = BLOCK_SIZE_IN_BYTES / WORD_SIZE;
global NUM_KECCAK_LANES: u32 = 25;

#[no_predicates]
pub fn keccak256<let N: u32>(input: [u8; N], message_size: u32) -> [u8; 32] {
    assert(N >= message_size);

    // Copy input to block bytes. For that we'll need at least input bytes (N)
    // but we want it to be padded to a multiple of BLOCK_SIZE_IN_BYTES.
    let mut block_bytes = [0; ((N / BLOCK_SIZE_IN_BYTES) + 1) * BLOCK_SIZE_IN_BYTES];
    if is_unconstrained() {
        for i in 0..message_size {
            block_bytes[i] = input[i];
        }
    } else {
        for i in 0..N {
            if i < message_size {
                block_bytes[i] = input[i];
            }
        }
    }

    //1. format_input_lanes
    let max_blocks = (N + BLOCK_SIZE_IN_BYTES) / BLOCK_SIZE_IN_BYTES;
    //maximum number of bytes to hash
    let real_max_blocks = (message_size + BLOCK_SIZE_IN_BYTES) / BLOCK_SIZE_IN_BYTES;
    let real_blocks_bytes = real_max_blocks * BLOCK_SIZE_IN_BYTES;

    block_bytes[message_size] = 1;
    block_bytes[real_blocks_bytes - 1] = 0x80;

    // populate a vector of 64-bit limbs from our byte array
    let mut sliced_buffer =
        [0; (((N / BLOCK_SIZE_IN_BYTES) + 1) * BLOCK_SIZE_IN_BYTES) / WORD_SIZE];
    for i in 0..sliced_buffer.len() {
        let limb_start = WORD_SIZE * i;

        let mut sliced = 0;
        let mut v = 1;
        for k in 0..WORD_SIZE {
            sliced += v * (block_bytes[limb_start + k] as Field);
            v *= 256;
        }

        sliced_buffer[i] = sliced as u64;
    }

    //2. sponge_absorb
    let mut state: [u64; NUM_KECCAK_LANES] = [0; NUM_KECCAK_LANES];
    // `real_max_blocks` is guaranteed to at least be `1`
    // We peel out the first block as to avoid a conditional inside of the loop.
    // Otherwise, a dynamic predicate can cause a blowup in a constrained runtime.
    for j in 0..LIMBS_PER_BLOCK {
        state[j] = sliced_buffer[j];
    }
    state = keccakf1600(state);

    let state = if is_unconstrained() {
        // When in an unconstrained runtime we can take advantage of runtime loop bounds,
        // thus allowing us to simplify the loop body.
        for i in 1..real_max_blocks {
            for j in 0..LIMBS_PER_BLOCK {
                state[j] = state[j] ^ sliced_buffer[i * LIMBS_PER_BLOCK + j];
            }
            state = keccakf1600(state);
        }

        state
    } else {
        // We store the intermediate states in an array to avoid having a dynamic predicate
        // inside the loop, which can cause a blowup in a constrained runtime.
        let mut intermediate_states = [state; (N + BLOCK_SIZE_IN_BYTES) / BLOCK_SIZE_IN_BYTES + 1];
        for i in 1..max_blocks {
            let mut previous_state = intermediate_states[i - 1];
            for j in 0..LIMBS_PER_BLOCK {
                previous_state[j] = previous_state[j] ^ sliced_buffer[i * LIMBS_PER_BLOCK + j];
            }
            intermediate_states[i] = keccakf1600(previous_state);
        }

        // We can then take the state as of `real_max_blocks`, ignoring later permutations.
        intermediate_states[real_max_blocks - 1]
    };

    //3. sponge_squeeze
    let mut result = [0; 32];
    for i in 0..4 {
        let lane = state[i] as Field;
        let lane_le: [u8; 8] = lane.to_le_bytes();
        for j in 0..8 {
            result[8 * i + j] = lane_le[j];
        }
    }
    result
}

63.source:
// "Human Passport's issuer signed a scoreV2 attestation for `recipient`, its
// score is at least `min_score` under scorer `scorer_id`, and it has not
// expired at `now`."
//
// Everything except the wallet. `human_passport_score` adds the wallet's own
// signature and the nullifier; `human-passport-real-issuer-check` runs this alone against an
// issuance read from Base, whose recipient key nobody here holds.
//
// WHO COUNTS AS THE ISSUER. The verifier publishes a Merkle root over leaves
//
//   keccak256(issuer_address[20] ++ passport_domain_separator[32] ++ schema_uid[32])
//
// one per (issuer key, GitcoinVerifier deployment, scoreV2 schema). All three
// belong in the leaf:
//   - the issuer key, because it is the only thing that signs;
//   - the domain separator, because it names the chain and the GitcoinVerifier
//     contract the signature was made for -- the same key signs on every chain;
//   - the schema uid, because it is derived from the resolver address and so
//     differs per chain, and because the `data` layout read below is only the
//     scoreV2 layout. A signature over another schema's data must not be read
//     as a score.
// A list rather than a constant so a rotated issuer key or a new chain is a
// new root the verifier publishes, not a new circuit.

use std;
use ::keccak256::keccak256;
use ::coinbase_libs::merkle;
use ::coinbase_libs::ethereum::derive_address_from_pubkey;
use crate::request::{PassportRequest, passport_digest};
use crate::score_data::parse_score_head;

pub fn issuer_leaf(
    issuer: [u8; 20],
    passport_domain_separator: [u8; 32],
    schema_uid: [u8; 32],
) -> [u8; 32] {
    let mut pre: [u8; 84] = [0; 84];
    for i in 0..20 {
        pre[i] = issuer[i];
    }
    for i in 0..32 {
        pre[20 + i] = passport_domain_separator[i];
        pre[52 + i] = schema_uid[i];
    }
    keccak256(pre, 84)
}

pub fn verify_score_statement<let N: u32>(
    // what the verifier reads
    signer_list_merkle_root: [u8; 32],
    min_score: u32,
    scorer_id: Field,
    now: u64,
    // what the issuer signed
    passport_domain_separator: [u8; 32],
    req: PassportRequest,
    data: [u8; N],
    data_len: u32,
    issuer_signature: [u8; 64],
    issuer_pubkey_x: [u8; 32],
    issuer_pubkey_y: [u8; 32],
    issuer_merkle_proof: [[u8; 32]; 8],
    issuer_leaf_index: u32,
    issuer_merkle_depth: u32,
) {
    // 0. The head first: it also bounds data_len, which keccak256 would
    //    otherwise refuse with no message at all.
    let head = parse_score_head(data, data_len);

    // 1. The issuer key signed exactly this request.
    let digest = passport_digest(passport_domain_separator, req, data, data_len);
    let valid = std::ecdsa_secp256k1::verify_signature(
        issuer_pubkey_x,
        issuer_pubkey_y,
        issuer_signature,
        digest,
    );
    assert(valid, "Invalid issuer signature");

    // 2. That key, on that deployment, for that schema, is one the verifier
    //    accepts. The key is supplied by the prover; it is trusted only because
    //    the signature above verifies against it AND its leaf is in the list.
    let issuer = derive_address_from_pubkey(issuer_pubkey_x, issuer_pubkey_y);
    let leaf = issuer_leaf(issuer, passport_domain_separator, req.schema);
    let root = merkle::verify_merkle_proof(
        leaf,
        issuer_leaf_index,
        issuer_merkle_proof,
        issuer_merkle_depth,
    );
    assert(root == signer_list_merkle_root, "Issuer not in valid list");

    // 3. Not expired. EAS reads expirationTime 0 as "never"; Passport always
    //    sets one (90 days), and a statement about freshness cannot rest on an
    //    attestation that claims to last forever. `now < 0` is false for every
    //    u64, so this one comparison also refuses 0 -- a separate `!= 0` guard
    //    was unreachable (scripts/human-passport/mutation-check.sh showed it).
    assert(now < req.expiration_time, "Attestation expired");

    // 4. The score, read as the resolver reads it.
    assert(head.scorer_id == scorer_id, "Scorer id mismatch");
    assert(head.score >= min_score, "Score below threshold");
}

#[test]
fn leaf_binds_all_three_parts() {
    let a: [u8; 20] = [1; 20];
    let d: [u8; 32] = [2; 32];
    let s: [u8; 32] = [3; 32];
    let base = issuer_leaf(a, d, s);
    assert(base != issuer_leaf([4; 20], d, s));
    assert(base != issuer_leaf(a, [4; 32], s));
    assert(base != issuer_leaf(a, d, [4; 32]));
}

65.source:
// The digest Human Passport's issuer signs, rebuilt byte for byte.
//
// Source: GitcoinVerifier.sol (passportxyz/eas-proxy). verifyAndAttest() takes
// a PassportAttestationRequest and the issuer's v/r/s, and accepts it only
// when ECDSA.recover(toTypedDataHash(DOMAIN_SEPARATOR, hash), v, r, s) is the
// contract's `issuer`. The hash is EIP-712's hashStruct:
//
//   entry  = keccak(abi.encode(STAMP_TYPEHASH, recipient, expirationTime,
//                              revocable, refUID, keccak(data), value))
//   multi  = keccak(abi.encode(MULTI_TYPEHASH, schema,
//                              keccak(abi.encodePacked([entry]))))
//   struct = keccak(abi.encode(PASSPORT_TYPEHASH,
//                              keccak(abi.encodePacked([multi])), nonce, fee))
//   digest = keccak(0x1901 ++ domainSeparator ++ struct)
//
// ONE REQUEST WITH ONE ENTRY, BY CONSTRUCTION. Every scoreV2 issuance read on
// Base has that shape (one MultiAttestationRequest, one AttestationRequestData).
// The array hashes above are hashes of exactly one element, so a request the
// issuer signed with two entries cannot be presented here without a keccak
// collision -- there is no index a prover could choose to pick the
// convenient entry out of a larger signed batch.

use ::keccak256::keccak256;
use ::coinbase_libs::ethereum::create_eip712_digest;

/// keccak256("AttestationRequestData(address recipient,uint64 expirationTime,bool revocable,bytes32 refUID,bytes data,uint256 value)")
global STAMP_TYPEHASH: [u8; 32] = [
    0xd1, 0x83, 0xf8, 0x90, 0x34, 0x5d, 0x44, 0xab,
    0x79, 0x55, 0x5f, 0x4f, 0xbe, 0x54, 0xbb, 0xd5,
    0xe1, 0xd5, 0x54, 0x42, 0x00, 0x09, 0xef, 0xb2,
    0xb8, 0x42, 0x98, 0x2f, 0xad, 0x97, 0x79, 0xd5,
];

/// keccak256("MultiAttestationRequest(bytes32 schema,AttestationRequestData[] data)AttestationRequestData(...)")
global MULTI_TYPEHASH: [u8; 32] = [
    0xc8, 0x5e, 0xc0, 0xe2, 0xb4, 0xab, 0xf2, 0xa8,
    0xf3, 0x54, 0xa8, 0x52, 0x60, 0x48, 0x77, 0x05,
    0x64, 0x85, 0xcd, 0x77, 0xc2, 0xab, 0x27, 0x0f,
    0x97, 0x09, 0xbd, 0x19, 0x8e, 0x91, 0x87, 0x35,
];

/// keccak256("PassportAttestationRequest(MultiAttestationRequest[] multiAttestationRequest,uint256 nonce,uint256 fee)AttestationRequestData(...)MultiAttestationRequest(...)")
global PASSPORT_TYPEHASH: [u8; 32] = [
    0x0f, 0xd0, 0x04, 0x50, 0x07, 0x47, 0x19, 0x00,
    0x61, 0x1e, 0xfb, 0x46, 0x09, 0x70, 0xc7, 0xa3,
    0xa1, 0xec, 0xbb, 0xbb, 0xd5, 0xab, 0xcf, 0xb7,
    0xe4, 0x3e, 0x7c, 0xc2, 0xfe, 0x96, 0x35, 0x07,
];

/// The signed fields of the one AttestationRequestData, plus the request's
/// nonce and fee. Everything the issuer signed except `data`, which is passed
/// separately because its length varies.
pub struct PassportRequest {
    pub schema: [u8; 32],
    pub recipient: [u8; 20],
    pub expiration_time: u64,
    pub revocable: bool,
    pub ref_uid: [u8; 32],
    pub value: [u8; 32],
    pub nonce: [u8; 32],
    pub fee: [u8; 32],
}

fn put32<let M: u32>(buf: &mut [u8; M], at: u32, v: [u8; 32]) {
    for i in 0..32 {
        buf[at + i] = v[i];
    }
}

fn hash32(v: [u8; 32]) -> [u8; 32] {
    keccak256(v, 32)
}

/// hashStruct(PassportAttestationRequest) for a one-request, one-entry request.
pub fn passport_struct_hash<let N: u32>(
    req: PassportRequest,
    data: [u8; N],
    data_len: u32,
) -> [u8; 32] {
    let data_hash = keccak256(data, data_len);

    // abi.encode(STAMP_TYPEHASH, recipient, expirationTime, revocable, refUID,
    //            keccak(data), value): seven words.
    let mut entry: [u8; 224] = [0; 224];
    put32(&mut entry, 0, STAMP_TYPEHASH);
    for i in 0..20 {
        entry[32 + 12 + i] = req.recipient[i];
    }
    let exp_bytes: [u8; 8] = (req.expiration_time as Field).to_be_bytes();
    for i in 0..8 {
        entry[64 + 24 + i] = exp_bytes[i];
    }
    entry[96 + 31] = if req.revocable { 1 } else { 0 };
    put32(&mut entry, 128, req.ref_uid);
    put32(&mut entry, 160, data_hash);
    put32(&mut entry, 192, req.value);
    let entry_hash = keccak256(entry, 224);

    let mut multi: [u8; 96] = [0; 96];
    put32(&mut multi, 0, MULTI_TYPEHASH);
    put32(&mut multi, 32, req.schema);
    put32(&mut multi, 64, hash32(entry_hash));
    let multi_hash = keccak256(multi, 96);

    let mut outer: [u8; 128] = [0; 128];
    put32(&mut outer, 0, PASSPORT_TYPEHASH);
    put32(&mut outer, 32, hash32(multi_hash));
    put32(&mut outer, 64, req.nonce);
    put32(&mut outer, 96, req.fee);
    keccak256(outer, 128)
}

/// The 32 bytes the issuer's key signed.
pub fn passport_digest<let N: u32>(
    passport_domain_separator: [u8; 32],
    req: PassportRequest,
    data: [u8; N],
    data_len: u32,
) -> [u8; 32] {
    create_eip712_digest(passport_domain_separator, passport_struct_hash(req, data, data_len))
}

66.source:
// The `data` field of a Human Passport scoreV2 attestation, read the way
// Solidity reads it.
//
// The schema, from GitcoinResolver._setScoreV2 (passportxyz/eas-proxy):
//
//   abi.decode(data, (bool, uint8, uint128, uint32, uint32, Stamp[]))
//                     passing  decimals  scorer_id  score  threshold  stamps
//
// Every static field is one 32-byte word in the head, so the five values this
// circuit needs sit at fixed offsets and do not depend on how many stamps
// follow. The stamps are not parsed: they matter only because the issuer's
// signature covers keccak256(data), which `request.nr` computes over the whole
// thing.
//
// WHY THE HIGH BYTES ARE CHECKED. abi.decode reverts on a word whose unused
// high bytes are not zero, so data with dirty padding never became an
// attestation on chain. Reading only the low bytes here would accept bytes
// Solidity refuses -- the circuit would then disagree with the contract about
// what the score is. The issuer signs the data, so a prover cannot invent such
// bytes; the check keeps the two readings identical anyway, and costs nothing
// next to the keccak.

pub global HEAD_BYTES: u32 = 192;

/// Offset of the stamps array, relative to the start of `data`: six head words.
global STAMPS_OFFSET: u8 = 0xc0;

/// Passport writes four decimals (score 25.1234 is 251234). The resolver
/// rescales other values; this circuit does not -- a different number would
/// change what `min_score` means, so it is refused rather than guessed.
pub global SCORE_DECIMALS: u8 = 4;

pub struct ScoreHead {
    pub passing: bool,
    pub scorer_id: Field,
    pub score: u32,
    pub threshold: u32,
}

/// Big-endian value of the low `width` bytes of head word `word`, and whether
/// the word's other bytes are all zero. The caller asserts the second with a
/// message naming the field.
fn word_tail<let N: u32>(data: [u8; N], word: u32, width: u32) -> (Field, bool) {
    let start = word * 32;
    let mut acc: Field = 0;
    let mut high: u32 = 0;
    for i in 0..32 {
        let b = data[start + i];
        if i < 32 - width {
            high += b as u32;
        } else {
            acc = acc * 256 + b as Field;
        }
    }
    (acc, high == 0)
}

pub fn parse_score_head<let N: u32>(data: [u8; N], data_len: u32) -> ScoreHead {
    assert(data_len >= HEAD_BYTES, "score data shorter than its head");
    assert(data_len <= N, "score data longer than the circuit allows");

    let (passing, clean) = word_tail(data, 0, 1);
    assert(clean, "score data: passing has non-zero padding");
    assert((passing == 0) | (passing == 1), "score data: passing is not a bool");

    let (decimals, clean) = word_tail(data, 1, 1);
    assert(clean, "score data: decimals has non-zero padding");
    assert(decimals == SCORE_DECIMALS as Field, "score data: decimals is not 4");

    let (scorer_id, clean) = word_tail(data, 2, 16);
    assert(clean, "score data: scorer_id has non-zero padding");

    let (score, clean) = word_tail(data, 3, 4);
    assert(clean, "score data: score has non-zero padding");

    let (threshold, clean) = word_tail(data, 4, 4);
    assert(clean, "score data: threshold has non-zero padding");

    // Standard ABI encoding puts the only dynamic member right after the head.
    // Anything else is not what the resolver decodes.
    let (stamps_offset, clean) = word_tail(data, 5, 1);
    assert(clean, "score data: stamps offset has non-zero padding");
    assert(stamps_offset == STAMPS_OFFSET as Field, "score data: stamps offset is not 0xc0");

    ScoreHead {
        passing: passing == 1,
        scorer_id,
        score: score as u32,
        threshold: threshold as u32,
    }
}

// ---------------------------------------------------------------------------

#[test]
fn reads_each_head_field() {
    let mut d: [u8; 256] = [0; 256];
    d[31] = 1; // passing
    d[63] = 4; // decimals
    d[94] = 0x01;
    d[95] = 0x4f; // scorer 335
    d[124] = 0x00;
    d[125] = 0x03;
    d[126] = 0xd5;
    d[127] = 0x12; // score 251154
    d[158] = 0x4e;
    d[159] = 0x20; // threshold 20000
    d[191] = 0xc0;
    let h = parse_score_head(d, 224);
    assert(h.passing);
    assert(h.scorer_id == 335);
    assert(h.score == 251154);
    assert(h.threshold == 20000);
}

#[test(should_fail_with = "score data: decimals is not 4")]
fn other_decimals_are_refused() {
    let mut d: [u8; 256] = [0; 256];
    d[63] = 2;
    d[191] = 0xc0;
    let _ = parse_score_head(d, 224);
}

#[test(should_fail_with = "score data: score has non-zero padding")]
fn dirty_score_padding_is_refused() {
    let mut d: [u8; 256] = [0; 256];
    d[63] = 4;
    d[100] = 1; // inside the score word, above its four bytes
    d[191] = 0xc0;
    let _ = parse_score_head(d, 224);
}

#[test(should_fail_with = "score data shorter than its head")]
fn a_short_head_is_refused() {
    let d: [u8; 256] = [0; 256];
    let _ = parse_score_head(d, 191);
}

#[test(should_fail_with = "score data: passing is not a bool")]
fn a_non_bool_passing_word_is_refused() {
    let mut d: [u8; 256] = [0; 256];
    d[31] = 2;
    d[63] = 4;
    d[191] = 0xc0;
    let _ = parse_score_head(d, 224);
}

